class TextModerationResult:
    text: str
    is_unsafe: bool
    scores: Dict[str, float]
    unsafe_spans: List[Dict[str, Any]]

@dataclass
class BatchModerationRequest:
    texts: List[str]
    client_ref_ids: Optional[List[str]] = None

@dataclass
class BatchModerationResult:
    results: List[TextModerationResult]

@dataclass
class RedactionResult:
    original_text: str
    redacted_text: str
    redacted_spans: List[Dict[str, Any]]

import os
import requests
from typing import Dict, Any, List, Optional

class SafetyClient:
    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.environ.get("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("PERSPECTIVE_API_KEY not found. Please set it as an environment variable or pass it during initialization.")
        self.perspective_api_url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    def moderate_text(self, text: str) -> Dict[str, Any]:
        payload = {"comment": {"text": text}, "languages": ["en"],
                   "requestedAttributes": {"TOXICITY": {}}, "doNotStore": True}
        response = requests.post(self.perspective_api_url,
            params={"key": self.api_key},
            json=payload, timeout=30)
        response.raise_for_status()
        return response.json()

    def redact_text(self, text: str, attributes: List[str] = ["TOXICITY"]) -> Dict[str, Any]:
        # This is a simplified example. Redaction logic would be more complex
        # and likely involve more advanced API features or post-processing.
        payload = {"comment": {"text": text}, "languages": ["en"],
                   "requestedAttributes": {attr: {} for attr in attributes}, "doNotStore": True}
        response = requests.post(self.perspective_api_url,
            params={"key": self.api_key},
            json=payload, timeout=30)
        response.raise_for_status()
        return response.json()

import os
from typing import Dict, Any, List
from openai import OpenAI

def moderation_summary(moderation_decisions: List[Dict[str, Any]]) -> str:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    # Prepare the input for the summarization model
    decision_texts = []
    for i, decision in enumerate(moderation_decisions):
        decision_texts.append(f"Decision {i+1}: Text: {decision.get("text", "N/A")}, Is Unsafe: {decision.get("is_unsafe", "N/A")}, Scores: {decision.get("scores", "N/A")}")

    prompt = "Summarize the following moderation decisions:\n" + "\n".join(decision_texts)

    try:
        response = client.chat.completions.create(
            model="gpt-3.5-turbo",  # Or "gpt-4"
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes moderation decisions."},
                {"role": "user", "content": prompt}
            ],
            max_tokens=150
        )
        summary = response.choices[0].message.content.strip()
        return summary
    except Exception as e:
        return f"Error summarizing moderation decisions: {e}"
